    sys.exit(2)
if "files" not in treeData or not isinstance(treeData["files"], list):
    sys.stderr.write("tree response missing files list\n")
    sys.exit(2)
wfList = []
for entry in treeData["files"]:
    if isinstance(entry, str) and entry.startswith(".github/workflows/"):
        wfList.append(entry)
wfInfo = []
bestPath = ""
bestTool = ""
for wfPath in wfList:
    try:
        docResp = requests.get(baseUrl + "/api/repo/paiement-api/file", headers=authHeader, params={"path": wfPath}, timeout=20)
    except Exception as err:
        sys.stderr.write("doc request failed: " + str(err) + "\n")
        sys.exit(2)
    if docResp.status_code != 200:
        sys.stderr.write("doc request failed with status " + str(docResp.status_code) + "\n")
        sys.exit(2)
