import requests
import json
import os
import sys
import re

try:
    base_url = os.environ["LAB_URL"]
    token = os.environ["LAB_TOKEN"]
except Exception:
    sys.stderr.write("missing LAB_URL or LAB_TOKEN\n")
    sys.exit(2)

base_url = base_url.rstrip("/")
headers = {"Authorization": "Bearer " + token}

queries = ["(login|authenticate|auth).*log", "logger\\.(info|warning|error)", "(authentication.*(success|fail)|login.*(success|fail))"]

all_matches = []
for q in queries:
    try:
        r = requests.get(base_url + "/api/repo/paiement-api/search", headers=headers, params={"q": q}, timeout=15)
    except Exception as e:
        sys.stderr.write("search request failed\n")
        sys.exit(2)
    if r.status_code != 200:
        sys.stderr.write("search request failed\n")
        sys.exit(2)
    try:
        data = r.json()
    except Exception:
        sys.stderr.write("search bad json\n")
        sys.exit(2)
    if "matches" not in data:
        sys.stderr.write("search missing matches\n")
        sys.exit(2)
    matches = data["matches"]
    if not isinstance(matches, list):
        sys.stderr.write("search matches not list\n")
        sys.exit(2)
    for m in matches:
        if not isinstance(m, dict):
            sys.stderr.write("search match not dict\n")
            sys.exit(2)
        if "path" not in m or "line" not in m or "text" not in m:
            sys.stderr.write("search match missing fields\n")
            sys.exit(2)
        all_matches.append(m)

unique_files = []
for m in all_matches:
    p = m.get("path")
    if not isinstance(p, str):
        sys.stderr.write("match path not str\n")
        sys.exit(2)
    if p not in unique_files:
        unique_files.append(p)

file_texts = {}
for p in unique_files:
    try:
        fr = requests.get(base_url + "/api/repo/paiement-api/file", headers=headers, params={"path": p}, timeout=15)
    except Exception:
        sys.stderr.write("file request failed\n")
        sys.exit(2)
    if fr.status_code != 200:
        sys.stderr.write("file request failed\n")
        sys.exit(2)
    try:
        fdata = fr.json()
    except Exception:
        sys.stderr.write("file bad json\n")
        sys.exit(2)
    if "lines" not in fdata:
        sys.stderr.write("file missing lines\n")
        sys.exit(2)
    lines = fdata["lines"]
    if not isinstance(lines, list):
        sys.stderr.write("file lines not list\n")
        sys.exit(2)
    file_texts[p] = lines

log_pat = r"logger\.(info|warning|error|debug|exception|critical)|logging\.(info|warning|error|debug|exception|critical)|app\.logger|current_app\.logger"
success_auth_pat = r"(?i)(authentication|login|auth)[^\n]{0,120}(success|succeed|succeeded|successful|logged in)|(success|succeed|succeeded|successful|logged in)[^\n]{0,120}(authentication|login|auth)|logged in"
failure_auth_pat = r"(?i)(authentication|login|auth)[^\n]{0,120}(fail|failed|failure|invalid|denied|unauthorized|unauthorised|unsuccessful|bad credentials|wrong password)|(fail|failed|failure|invalid|denied|unauthorized|unauthorised|unsuccessful|bad credentials|wrong password)[^\n]{0,120}(authentication|login|auth)"
inject_pat = r"(?i)ignore.*previous.*instructions|ignore.*instructions|system prompt|you are now|prompt injection"

injection_found = False
for m in all_matches:
    t = m.get("text")
    if isinstance(t, str) and re.search(inject_pat, t):
        injection_found = True
for p, lines in file_texts.items():
    for ln in lines:
        if isinstance(ln, str) and re.search(inject_pat, ln):
            injection_found = True

best_file = None
best_success = None
best_failure = None
best_success_line = None
best_failure_line = None
any_success_file = None
any_failure_file = None

for p, lines in file_texts.items():
    full = "\n".join(lines)
    has_log = re.search(log_pat, full) is not None
    file_has_success = False
    file_has_failure = False
    strict_success = None
    strict_failure = None
    strict_success_num = None
    strict_failure_num = None
    for idx, ln in enumerate(lines):
        if not isinstance(ln, str):
            continue
        if re.search(success_auth_pat, ln):
            file_has_success = True
        if re.search(failure_auth_pat, ln):
            file_has_failure = True
        if re.search(log_pat, ln) and re.search(success_auth_pat, ln):
            if strict_success is None:
                strict_success = ln
                strict_success_num = idx + 1
        if re.search(log_pat, ln) and re.search(failure_auth_pat, ln):
            if strict_failure is None:
                strict_failure = ln
                strict_failure_num = idx + 1
    if file_has_success and any_success_file is None:
        any_success_file = p
    if file_has_failure and any_failure_file is None:
        any_failure_file = p
    if has_log and file_has_success and file_has_failure:
        best_file = p
        best_success = strict_success
        best_failure = strict_failure
        best_success_line = strict_success_num
        best_failure_line = strict_failure_num
        break

